// This file is hand written and is not regenerated by `go generate
// ./internal/ent`: it lets a running process ask, through the client it
// already holds, whether the database under it has moved past what this build
// can serve.
package ent

import (
	"context"

	"github.com/Subject-Void-LLC/the-pleiades/internal/ent/migrate"
)

// InspectSchema reads the database's migration history through this client's
// own connection pool and says what this build makes of it, without changing
// anything (internal/ent/migrate.Inspect).
//
// A controller calls it on every heartbeat. A newer build that contracted the
// schema past this one's window is found here, and the controller stops
// serving rather than writing to tables it no longer understands.
func (c *Client) InspectSchema(ctx context.Context) (migrate.Plan, error) {
	db, dialectName, err := c.rawDB()
	if err != nil {
		return migrate.Plan{}, err
	}
	return migrate.Inspect(ctx, dialectName, db)
}
